def render(root,out):
 root=Path(root);out=Path(out);report=json.loads((root/'analysis/report-data/report.json').read_text());cp=paths(root);analyses=report['analyses'];primary=analyses[cp['primary_summary']];recent=analyses[cp['recent_summary']];hgb=analyses[cp['hgb_summary']];cohort=report['cohort']
